{
  "tables": [
    {
      "table_name": "market_data",
      "columns": [
        {
          "name": "data_id",
          "type": "INTEGER",
          "description": "Unique identifier for each market data entry"
        },
        {
          "name": "open_price",
          "type": "DECIMAL",
          "description": "Opening price of the cryptocurrency for the period"
        },
        {
          "name": "high_price",
          "type": "DECIMAL",
          "description": "Highest price of the cryptocurrency for the period"
        },
        {
          "name": "low_price",
          "type": "DECIMAL",
          "description": "Lowest price of the cryptocurrency for the period"
        },
        {
          "name": "close_price",
          "type": "DECIMAL",
          "description": "Closing price of the cryptocurrency for the period"
        },
        {
          "name": "volume",
          "type": "DECIMAL",
          "description": "Volume of trades during the period"
        },
        {
          "name": "close_time",
          "type": "TIMESTAMP",
          "description": "Timestamp when the market data entry was recorded"
        },
        {
          "name": "crypto_id",
          "type": "INTEGER",
          "description": "Identifier for the cryptocurrency to which this data pertains"
        },
        {
          "name": "exchange_id",
          "type": "INTEGER",
          "description": "Identifier for the exchange"
        },
        {
          "name": "currency_pair",
          "type": "VARCHAR",
          "description": "Trading pair for the data"
        },
        {
          "name": "price_change_percentage",
          "type": "DECIMAL",
          "description": "Percentage change in price"
        }
      ],
      "primary_key": [
        "data_id"
      ]
    },
    {
      "table_name": "cryptocurrencies",
      "columns": [
        {
          "name": "crypto_id",
          "type": "INTEGER",
          "description": "Unique identifier for each cryptocurrency"
        },
        {
          "name": "crypto_name",
          "type": "VARCHAR",
          "description": "Full name of the cryptocurrency"
        },
        {
          "name": "symbol",
          "type": "VARCHAR",
          "description": "Symbol or abbreviation of the cryptocurrency"
        },
        {
          "name": "market_cap",
          "type": "BIGINT",
          "description": "Market capitalization of the cryptocurrency"
        },
        {
          "name": "launch_date",
          "type": "DATE",
          "description": "Date when the cryptocurrency was launched"
        },
        {
          "name": "algorithm",
          "type": "VARCHAR",
          "description": "Algorithm used by the cryptocurrency"
        },
        {
          "name": "total_supply",
          "type": "BIGINT",
          "description": "Total supply of the cryptocurrency"
        }
      ],
      "primary_key": [
        "crypto_id"
      ]
    },
    {
      "table_name": "users",
      "columns": [
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "Unique identifier for each user"
        },
        {
          "name": "username",
          "type": "VARCHAR",
          "description": "Username of the user"
        },
        {
          "name": "email",
          "type": "VARCHAR",
          "description": "Email address of the user"
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "Role of the user on the platform (e.g., trader, analyst, admin)"
        },
        {
          "name": "registration_date",
          "type": "DATE",
          "description": "Date when the user registered on the platform"
        },
        {
          "name": "last_login",
          "type": "TIMESTAMP",
          "description": "Last login time of the user"
        },
        {
          "name": "status",
          "type": "VARCHAR",
          "description": "Account status of the user"
        }
      ],
      "primary_key": [
        "user_id"
      ]
    },
    {
      "table_name": "user_access_logs",
