        },
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "ID of the user accessing the data"
        },
        {
          "name": "data_id",
          "type": "INTEGER",
          "description": "ID of the market data being accessed"
        },
        {
          "name": "access_time",
          "type": "TIMESTAMP",
          "description": "Timestamp when the access occurred"
        },
        {
          "name": "access_type",
          "type": "VARCHAR",
          "description": "Type of access (e.g., view, download)"
